// Fixed series-focused keywords
const keywords = [
  { keyword: 'مسلسل تركي مدبلج بالعربية الحلقة 1', category: 'drama' },
  { keyword: 'مسلسل هندي مدبلج عربي الحلقة 1', category: 'drama' },
  { keyword: 'مسلسل كوري مترجم عربي ep1', category: 'drama' },
  { keyword: 'مسلسل مغربي دارجة الحلقة الأولى', category: 'drama' },
  { keyword: 'مسلسل صيني مدبلج عربي الحلقة 1', category: 'drama' },
  { keyword: 'مسلسل تركي رومانسي الحلقة الاولى مدبلج', category: 'romance' }
];
return keywords.map(k => ({ json: k }));

const body = $input.first().json;
const kw = $('Series Keywords').item.json;
const items = body?.items || [];
const videoIds = items.map(i => i.id?.videoId).filter(Boolean).join(',');
if (!videoIds) return [{ json: { candidates: [], keyword: kw.keyword } }];
return [{ json: { videoIds, keyword: kw.keyword, category: kw.category || 'drama', items } }];

const details = $input.first().json;
const prev = $('Extract IDs').item.json;
const keyword = prev.keyword || '';
const category = prev.category || 'drama';
const videos = details?.items || [];

function isoToDur(iso) {
  if (!iso) return 0;
  const m = iso.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
  if (!m) return 0;
  return (parseInt(m[1]||0)*3600) + (parseInt(m[2]||0)*60) + (parseInt(m[3]||0));
}

function detectOrigin(t) {
  const tl = t.toLowerCase();
  if (/تركي|turkish/.test(tl)) return 'turkish';
  if (/هندي|hindi|bollywood/.test(tl)) return 'indian';
  if (/كوري|korean/.test(tl)) return 'korean';
  if (/صيني|chinese/.test(tl)) return 'chinese';
  if (/مغربي|maroc|darija/.test(tl)) return 'moroccan';
  return 'other';
}

function extractEpisode(title) {
  const m = title.match(/الحلقة\s*(\d+)|[Ee]p(?:isode)?\s*(\d+)|[Ee](\d+)/);
  return m ? parseInt(m[1]||m[2]||m[3]) : null;
}

function extractSeries(title) {
  // Strip episode number from title to get series name
  return title
    .replace(/الحلقة\s*\d+.*$/i, '')
    .replace(/[Ee]p(?:isode)?\s*\d+.*$/i, '')
    .replace(/[Ss]\d+[Ee]\d+.*$/i, '')
    .trim();
}

const MIN_EP_DUR = 900; // 15 min

const candidates = videos
  .filter(v => {
    const dur = isoToDur(v.contentDetails?.duration);
    return v.status?.embeddable !== false &&
           v.snippet?.liveBroadcastContent !== 'live' &&
           dur >= MIN_EP_DUR;
  })
  .map(v => {
    const dur = isoToDur(v.contentDetails?.duration);
    const title = v.snippet?.title || '';
    const epNum = extractEpisode(title);
    const seriesTitle = extractSeries(title);
    const year = parseInt(v.snippet?.publishedAt?.slice(0,4)) || null;
    return {
      platform: 'youtube',
      platform_id: v.id,
      title_raw: title,
      type: 'episode',
      origin: detectOrigin(title),
      language: 'ar_dubbed',
      category,
      year,
      duration_sec: dur,
      poster_url: v.snippet?.thumbnails?.high?.url || v.snippet?.thumbnails?.medium?.url || null,
      embeddable: true,
      series_title: seriesTitle || title,
      episode_num: epNum || 1,
      season: 1,
      keyword,
      source_workflow: '03-youtube-discover-series'
    };
  });

console.log(`[YT Series] ${keyword} → ${candidates.length} episodes`);
return [{ json: { candidates, keyword } }];
